Definition cnt (l : list Z) (w : Z) : Z := Z.of_nat (count_occ Z.eq_dec l w).

(* [comment removed for export] *)
Fixpoint zsum (n : nat) (f : Z -> Z) : Z :=
  match n with O => 0 | S n' => zsum n' f + f (Z.of_nat n') end.

