  (* [comment removed for export] *)
  Lemma shift_rank_spec scale : 0 <= scale -> forall fuel s rank, Z.of_nat fuel <= s + 1 -> s - Z.of_nat fuel - scale >= -1 -> s < Zlength rank ->
    0 <= s - Z.of_nat fuel + 1 - scale ->
    exists rank', shift_rank fuel s scale rank = Ok rank' /\ Zlength rank' = Zlength rank /\
      forall j, 0 <= j -> Znth j rank' = (if (s - Z.of_nat fuel <? j) && (j <=? s) then Znth (j - scale) rank else Znth j rank).
