  Lemma zero_rank_spec : forall fuel s rank, Z.of_nat fuel <= s + 1 -> 0 <= s - Z.of_nat fuel + 1 -> s < Zlength rank ->
    exists rank', zero_rank fuel s rank = Ok rank' /\ Zlength rank' = Zlength rank /\
      forall j, 0 <= j -> Znth j rank' = (if (s - Z.of_nat fuel <? j) && (j <=? s) then 0 else Znth j rank).
Proof.
