  Lemma rescale_spec ws rank nbS tl target : WF ws rank nbS tl -> 1 <= target <= 12 ->
    exists ws' rank' tl', rescale ws rank nbS tl target = Ok (ws', rank', tl') /\ WF ws' rank' nbS tl' /\
      tl' = Z.max tl target.
Proof.
