    Hypothesis W : WF ws rank nbS tl.
    Let Tn : nat := Z.to_nat (tl + 1).

    Definition RSum (n : nat) : Z := zsum n (fun m => Znth m rank).      (* [comment removed for export] *)
    Definition U (n : nat) : Z := zsum n (fun m => cnt ws m * kw m).     (* [comment removed for export] *)

    Lemma W_facts : 1 <= tl <= 12 /\ Zlength ws = nbS /\ 2 <= nbS <= 256 /\ Zlength rank = 13.
