    (* [comment removed for export] *)
    Definition SEG (k : nat) (syms : list (option Z)) : Prop :=
      length syms = 256%nat /\
      forall w, (w < Tn)%nat -> forall i, RSum w <= i < RSum w + cnt (firstn k ws) (Z.of_nat w) ->
        exists v, nth (Z.to_nat i) syms None = Some v /\ 0 <= v < nbS.

    Lemma cnt_firstn_le k l w : cnt (firstn k l) w <= cnt l w.
Proof.
