    Lemma cnt_firstn_S k w : (k < length ws)%nat ->
      cnt (firstn (S k) ws) w = cnt (firstn k ws) w + (if nth k ws 0 =? w then 1 else 0) /\
      (nth k ws 0 = w -> cnt (firstn k ws) w + 1 <= cnt ws w).
Proof.
