    Lemma sort_spec : forall fuel k rs syms, (k + fuel = Z.to_nat nbS)%nat -> Zlength rs = 13 ->
      (forall w, (w < Tn)%nat -> Znth (Z.of_nat w) rs = RSum w + cnt (firstn k ws) (Z.of_nat w)) ->
      SEG k syms ->
      exists rs' syms', sort_loop fuel (Z.of_nat k) ws rs syms = Ok (rs', syms') /\ SEG (Z.to_nat nbS) syms'.
