    (* [comment removed for export] *)
    Definition CI (u : Z) (cells : list (option deltX1)) : Prop :=
      Zlength cells = 2^(L + 1) /\
      forall i, 0 <= i < u -> exists c, nth (Z.to_nat i) cells None = Some c /\ 1 <= x1_nbBits c <= tl /\ 0 <= x1_byte c < 256.

    Lemma ostoreX_ok l i v : 0 <= i < Zlength l ->
      ostoreX l i v = Ok (firstn (Z.to_nat i) l ++ Some v :: skipn (S (Z.to_nat i)) l) /\
      length (firstn (Z.to_nat i) l ++ Some v :: skipn (S (Z.to_nat i)) l) = length l /\
      forall j, nth j (firstn (Z.to_nat i) l ++ Some v :: skipn (S (Z.to_nat i)) l) None = (if Nat.eqb j (Z.to_nat i) then Some v else nth j l None).
