    Lemma fill_cells_spec c : 1 <= x1_nbBits c <= tl -> 0 <= x1_byte c < 256 ->
      forall k cells u, 0 <= u -> u + Z.of_nat k <= Zlength cells -> CI u cells ->
      exists cells', fill_cells k cells u c = Ok cells' /\ CI (u + Z.of_nat k) cells'.
Proof.
