    Lemma fill_syms_spec syms (w : nat) nbBits : SEG (Z.to_nat nbS) syms -> (1 <= w < Tn)%nat -> 1 <= nbBits <= tl -> tl <= L + 1 ->
      forall fuel s cells, 0 <= s <= cnt ws (Z.of_nat w) -> cnt ws (Z.of_nat w) - s < Z.of_nat fuel ->
        CI (U w + s * kw (Z.of_nat w)) cells ->
        exists cells', fill_syms fuel s (cnt ws (Z.of_nat w)) (RSum w) (kw (Z.of_nat w)) nbBits syms cells (U w + s * kw (Z.of_nat w))
